ltac2:(KReplay.run1 (kr_t_MI_Geom ()) ["CEIL_WRAP_1"; "GEOM"] (Mh_0049_blobs1.kr_b_097 ())). Qed.

Lemma hosts_mem b m : hosts st b m -> m_mem (R m) = Some b.
