Proof.
ltac2:(KReplay.run1 (kr_t_MI_Geom ()) ["CEIL_WRAP_1"; "GEOM"] (Mh_0049_blobs1.kr_b_107 ())). Qed.

Lemma sstart_lt b m i j : hosts st b m -> i < j -> sstart (R m) i + get_stride (R m) <= sstart (R m) j.
Proof.
ltac2:(KReplay.run1 (kr_t_MI_Geom ()) ["CEIL_WRAP_1"; "GEOM"] (Mh_0049_blobs1.kr_b_108 ())). Qed.

Lemma sstart0 b m : hosts st b m -> sstart (R m) 0 = snd b + UNIT.
