Proof.
ltac2:(KReplay.run1 (kr_t_MI_Read ()) ["CEIL_WRAP_1"] (Mh_0049_blobs1.kr_b_218 ())). Qed.
Lemma byte_of_1 x : 0 <= x -> byte_of x 1 = (x / 256) mod 256.
Proof.
ltac2:(KReplay.run1 (kr_t_MI_Read ()) ["CEIL_WRAP_1"] (Mh_0049_blobs1.kr_b_219 ())). Qed.
