  INVL X st L BL LS -> s_regions st !! rid = Some r -> fst p = rid -> frontier st rid r <= snd p ->
  s_areas st !! p = None /\ forall k, 0 <= k < NSLOTS -> s_metas st !! mslot p k = None.
